_perceive() {
  const a = this.a;
  const eye = _v.copy(a.pos); eye.y += 1.3;
  let best = null, bd = Infinity;
  const aw = this.diff.awareness;
  for (const e of G.actors) {
    if (e.team === a.team || !e.alive) continue;
    const d = e.pos.distanceTo(a.pos);
    if (d > aw) continue;
    const swimming = e.anim.form === 'swim';
    if (swimming && d > 3 && !(d < 9 && Math.hypot(e.vel.x, e.vel.z) > 7)) continue;
    // A worse candidate cannot replace the best even if visible. Avoid its expensive raycast.
    // Preserve the -4 existing-target bias and the original strict tie break.
    const score = d - (e === this.target ? 4 : 0);
    if (score >= bd) continue;
    _v2.copy(e.pos); _v2.y += e.form === 'squid' ? 0.3 : 1.0;
    if (!G.physics.los(eye, _v2)) continue;
    if (score < bd) { bd = score; best = e; }
  }
  this._combatDirectTarget = best && Math.abs(best.pos.y - a.pos.y) < 0.9 &&
    best.pos.distanceTo(a.pos) <= Math.max(3, this._range()) &&
    this._fatLos(a.pos.x, a.pos.y, a.pos.z, best.pos.x, best.pos.y, best.pos.z) &&
    this._dryLine(a.pos.x, a.pos.y, a.pos.z, best.pos.x, best.pos.z) ? best : null;
  if (best) {
    if (best !== this.target) {
      this.target = best; this.react = this.diff.reaction * (0.7 + Math.random() * 0.6); this.repath = 0;
      // first look lands a little off (over- or under-shoot) and settles — like a human flick
      this.acqT = 0; this.acqSignY = (Math.random() < 0.5 ? -1 : 1) * (0.5 + Math.random() * 0.5); this.acqSignP = (Math.random() - 0.5) * 1.2;
    }
    this.seeTimer = 1.2;
    this.lostTimer = 0;
  } else {
    this.seeTimer -= 0.2;
    if (this.target) {
      this.lostTimer += 0.2;
      if (this.lostTimer > 2.5 || this.target.pos.distanceTo(a.pos) > aw + 6) this.target = null;
    }
  }
  this.react -= 0.2;
}

_pickPaintGoal:
_pickPaintGoal() {
  const a = this.a, nav = G.nav;
  const choices = this._paintChoices || (this._paintChoices = []); choices.length = 0;
  const choicePool = this._paintChoicePool || (this._paintChoicePool = []);
  const enemyPad = G.level.spawnPads[1 - a.team];
  const ownPad = G.level.spawnPads[a.team];
  const total = ownPad.distanceTo(enemyPad);
  const mates = this._mates || (this._mates = []); mates.length = 0;
  for (let i = 0; i < G.actors.length; i++) { const o = G.actors[i]; if (o !== a && o.team === a.team && o.bot) mates.push(o); }
  const candidates = G.level.native ? nativePaintGoalIds(this, G) : nav.validIds;
  for (let i = 0; i < 16; i++) {
    if (!candidates.length) break;
    const id = candidates[(Math.random() * candidates.length) | 0];
    const n = nav.nodes[id];
    if (!n) break;
    if (n.zone >= 0) continue;
    const d = Math.hypot(n.x - a.pos.x, n.z - a.pos.z);
    if (d > 34 || d < 2.5 || !botGoalAllowed(this, nav, n)) continue;
    const st = G.paint.regionStats(n.x, n.y, n.z, 3.5, a.team, _stats);
    if (!st.n) continue;
    const progress = 1 - Math.hypot(n.x - enemyPad.x, n.z - enemyPad.z) / total; // 0 at own base → 1 at enemy base
    let score = (st.empty + st.enemy * 1.25) * 12 - d * 0.18 + clamp(progress, 0, 0.8) * 4 + Math.random() * 2.5;
    for (const m of mates) if (m.alive && m.bot.mode === 'paint' && m.bot.path && m.bot.goal >= 0) { const g = nav.nodes[m.bot.goal]; if (g && Math.abs(g.y - n.y) < 1.2 && Math.abs(g.x - n.x) < 7 && Math.abs(g.z - n.z) < 7 && Math.hypot(g.x - n.x, g.z - n.z) < 7) score -= 4; }
    let entry = choicePool[choices.length];
    if (!entry) entry = choicePool[choices.length] = { id: 0, score: 0 };
    entry.id = id; entry.score = score;
    choices.push(entry);
  }
  this.goalTimer = 4 + Math.random() * 3;
  choices.sort((a, b) => b.score - a.score);
  // Try at most three distinct goals. A one-way drop or isolated height must
  // not trigger sixteen new paint scans on every simulation tick.
  const tried = this._triedGoals || (this._triedGoals = new Set()); tried.clear();
  for (const choice of choices) {
    if (tried.has(choice.id)) continue;
    if (tried.size >= 3) break;
    tried.add(choice.id);
    const n = nav.nodes[choice.id];
    if (this._pathTo(n, 0.3, choice.id)) return;
    rememberBotGoalFailure(this, nav, choice.id);
  }
  this.path = null; this.goal = -1;
  this.goalTimer = 0.6 + Math.random() * 0.4;
}
